public java.util.List<java.util.List<Integer>> permute(int[] nums) {
    java.util.List<java.util.List<Integer>> result = new java.util.ArrayList<>();
    if (nums == null || nums.length == 0) {
        return result;
    }
    // Start with the first element as the initial permutation
    java.util.List<Integer> first = new java.util.ArrayList<>();
    first.add(nums[0]);
    result.add(first);
    // For each remaining number, insert it into every possible position
    for (int i = 1; i < nums.length; i++) {
        int num = nums[i];
        java.util.List<java.util.List<Integer>> temp = new java.util.ArrayList<>();
        for (java.util.List<Integer> perm : result) {
            for (int pos = 0; pos <= perm.size(); pos++) {
                java.util.List<Integer> newPerm = new java.util.ArrayList<>(perm);
                newPerm.add(pos, num);
                temp.add(newPerm);
            }
        }
        result = temp;
    }
    return result;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        minLen = Math.min(minLen, s.length());
    }
    String first = strings.get(0);
    java.util.List<String> reverses = new java.util.ArrayList<>();
    for (String s : strings) {
        reverses.add(new StringBuilder(s).reverse().toString());
    }
    for (int len = minLen; len > 0; len--) {
        java.util.Set<String> candidates = new java.util.HashSet<>();
        for (int i = 0; i + len <= first.length(); i++) {
            candidates.add(first.substring(i, i + len));
        }
        for (String sub : candidates) {
            boolean ok = true;
            for (int idx = 0; idx < strings.size(); idx++) {
                String current = strings.get(idx);
                if (!(current.contains(sub) || reverses.get(idx).contains(sub))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int count = 0;
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                count++;
                java.util.Deque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;

                while (!stack.isEmpty()) {
                    int[] cell = stack.pop();
                    int cr = cell[0];
                    int cc = cell[1];

                    for (int i = 0; i < 8; i++) {
                        int nr = cr + dr[i];
                        int nc = cc + dc[i];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                                && !visited[nr][nc] && grid[nr][nc] == '@') {
                            visited[nr][nc] = true;
                            stack.push(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }
    return count;
}

