public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null) {
        return "cannot be travelled";
    }
    java.util.String startKey = java.util.Arrays.toString(start);
    java.util.String endKey = java.util.Arrays.toString(end);
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }
    java.util.Map<java.util.String, java.util.Set<java.util.String>> graph = new java.util.HashMap<>();
    int dim = start.length;
    for (int[] path : paths) {
        if (path == null || path.length != dim * 2) {
            continue; // ignore invalid path entries
        }
        int[] coord1 = new int[dim];
        int[] coord2 = new int[dim];
        for (int i = 0; i < dim; i++) {
            coord1[i] = path[i];
            coord2[i] = path[dim + i];
        }
        java.util.String key1 = java.util.Arrays.toString(coord1);
        java.util.String key2 = java.util.Arrays.toString(coord2);
        graph.computeIfAbsent(key1, k -> new java.util.HashSet<>()).add(key2);
        graph.computeIfAbsent(key2, k -> new java.util.HashSet<>()).add(key1);
    }
    java.util.Queue<java.util.String> queue = new java.util.ArrayDeque<>();
    java.util.Set<java.util.String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        java.util.String current = queue.poll();
        java.util.Set<java.util.String> neighbors = graph.getOrDefault(current, java.util.Collections.emptySet());
        for (java.util.String neighbor : neighbors) {
            if (!visited.contains(neighbor)) {
                if (neighbor.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }
    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    int commonCount = 0;
    String w1 = word1 != null ? word1 : "";
    String w2 = word2 != null ? word2 : "";
    for (int i = 0; i < w1.length(); i++) {
        if (w2.indexOf(w1.charAt(i)) != -1) {
            commonCount++;
        }
    }
    for (int i = 0; i < w2.length(); i++) {
        if (w1.indexOf(w2.charAt(i)) != -1) {
            commonCount++;
        }
    }
    int denom = w1.length() + w2.length();
    String prefix = "appx(" + word1 + ", " + word2 + ") = ";
    if (commonCount == 0) {
        return prefix + "0";
    }
    // Reduce the fraction
    int a = commonCount;
    int b = denom;
    int temp;
    while (b != 0) {
        temp = a % b;
        a = b;
        b = temp;
    }
    int gcd = a;
    int num = commonCount / gcd;
    int den = denom / gcd;
    if (num == 1 && den == 1) {
        return prefix + "1";
    }
    return prefix + num + "/" + den;
}

public static String convertDatesToWeekdays(String date) {
