public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length == 0 || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 == 1) {
        return false; // cannot pair all elements
    }

    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k; // handle negative numbers
        freq[rem]++;
    }

    // remainder 0 must have even count
    if (freq[0] % 2 != 0) {
        return false;
    }

    // if k is even, remainder k/2 must also have even count
    if (k % 2 == 0 && freq[k / 2] % 2 != 0) {
        return false;
    }

    // For all other remainders, freq[r] must equal freq[k - r]
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) {
            // already handled k even case
            continue;
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] adj = new List[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new ArrayList<>();
    }
    for (int[] e : edges) {
        int u = e[0], v = e[1];
        adj[u].add(v);
        adj[v].add(u);
    }
    return dfs(0, -1, adj, hasApple);
}

private int dfs(int node, int parent, List<Integer>[] adj, boolean[] hasApple) {
    int total = 0;
    for (int child : adj[node]) {
        if (child == parent) continue;
        int childTime = dfs(child, node, adj, hasApple);
        if (childTime > 0 || hasApple[child]) {
            total += childTime + 2;
        }
    }
    return total;
}

public String sortString(String s) {
    int n = s.length();
    if (n == 0) return "";
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        freq[c - 'a']++;
    }
    StringBuilder sb = new StringBuilder(n);
    while (sb.length() < n) {
        // Ascending part
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                sb.append((char) (i + 'a'));
                freq[i]--;
                for (int j = i + 1; j < 26; j++) {
                    if (freq[j] > 0) {
                        sb.append((char) (j + 'a'));
                        freq[j]--;
                    }
                }
                break;
            }
        }
        // Descending part
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                sb.append((char) (i + 'a'));
                freq[i]--;
                for (int j = i - 1; j >= 0; j--) {
                    if (freq[j] > 0) {
                        sb.append((char) (j + 'a'));
                        freq[j]--;
                    }
                }
                break;
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 0) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    int mid = n / 2;
    int len1 = mid;
    int len2 = n - mid;
    java.util.HashMap<Integer, java.util.HashSet<Integer>> map1 = new java.util.HashMap<>();
    java.util.HashMap<Integer, java.util.HashSet<Integer>> map2 = new java.util.HashMap<>();
    // Enumerate subsets for first half
    for (int mask = 0; mask < (1 << len1); mask++) {
        int sum = 0;
        int size = 0;
        for (int i = 0; i < len1; i++) {
            if ((mask >> i) & 1) {
                sum += nums[i];
                size++;
            }
        }
        java.util.HashSet<Integer> set = map1.computeIfAbsent(size, k -> new java.util.HashSet<>());
        set.add(sum);
    }
    // Enumerate subsets for second half
    for (int mask = 0; mask < (1 << len2); mask++) {
        int sum = 0;
        int size = 0;
        for (int i = 0; i < len2; i++) {
            if ((mask >> i) & 1) {
                sum += nums[mid + i];
                size++;
            }
        }
        java.util.HashSet<Integer> set = map2.computeIfAbsent(size, k -> new java.util.HashSet<>());
        set.add(sum);
    }
    // Check possible split sizes
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        for (int size1 = 0; size1 <= k; size1++) {
            int size2 = k - size1;
            java.util.HashSet<Integer> set1 = map1.get(size1);
            java.util.HashSet<Integer> set2 = map2.get(size2);
            if (set1 == null || set2 == null) continue;
            for (int s1 : set1) {
                if (set2.contains(target - s1)) return true;
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return 0;
    int prev2 = 0; // cost for step -1 (starting before first step)
    int prev1 = 0; // cost for step 0 (starting before second step)
    for (int i = 2; i <= n; i++) {
        int costForPrevStep = prev1 + cost[i - 1];
        int costForPrevPrevStep = prev2 + cost[i - 2];
        int curr = Math.min(costForPrevStep, costForPrevPrevStep);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

