public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxSum = Integer.MIN_VALUE;
    int minSum = Integer.MAX_VALUE;
    int currentMax = 0;
    int currentMin = 0;
    for (int num : nums) {
        currentMax = Math.max(num, currentMax + num);
        maxSum = Math.max(maxSum, currentMax);
        currentMin = Math.min(num, currentMin + num);
        minSum = Math.min(minSum, currentMin);
    }
    return Math.max(Math.abs(maxSum), Math.abs(minSum));
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) return 0; // k is guaranteed positive, but guard anyway
    int[] fibs = new int[50];
    fibs[0] = 1;
    fibs[1] = 1;
    int sz = 2;
    while (true) {
        int next = fibs[sz - 1] + fibs[sz - 2];
        if (next > k) break;
        fibs[sz++] = next;
    }
    int count = 0;
    int remaining = k;
    for (int i = sz - 1; i >= 0 && remaining > 0; i--) {
        while (remaining >= fibs[i]) {
            remaining -= fibs[i];
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    List<Integer> small = new ArrayList<>();
    List<Integer> large = new ArrayList<>();
    int limit = (int)Math.sqrt(n);
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            small.add(i);
            int counterpart = n / i;
            if (counterpart != i) {
                large.add(counterpart);
            }
        }
    }
    // large factors are in descending order; reverse to ascending
    Collections.reverse(large);
    // Combine small and large
    for (int factor : large) {
        small.add(factor);
    }
    if (k <= 0 || k > small.size()) {
        return -1;
    }
    return small.get(k - 1);
}

public String makeGood(String s) {
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char last = stack.charAt(len - 1);
            if (Math.abs(last - c) == 32) { // 'A' to 'Z' difference is 32
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

