private int dfs(int index, java.util.Set<String> used, String s) {
    if (index == s.length()) {
        return 0;
    }
    int best = 0;
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (!used.contains(sub)) {
            used.add(sub);
            int curr = 1 + dfs(end, used, s);
            if (curr > best) {
                best = curr;
            }
            used.remove(sub);
        }
    }
    return best;
}

public int minOperations(String[] logs) {
    int depth = 0;
    for (String log : logs) {
        if ("./".equals(log)) {
            // Current directory, no change in depth
            continue;
        } else if ("../".equals(log)) {
            // Move up one directory if possible
            if (depth > 0) {
                depth--;
            }
        } else {
            // Enter a new directory
            depth++;
        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    // start with all 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int remaining = k - n; // need to add this many to reach sum k
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining);
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

