public static int singleNumber(int[] nums) {
    int ones = 0;
    int twos = 0;
    for (int num : nums) {
        // Update twos with bits that appear twice
        twos |= ones & num;
        // Update ones with bits that appear once
        ones ^= num;
        // Mask for bits that have appeared three times
        int commonMask = ones & twos;
        // Remove bits that have appeared three times from ones and twos
        ones &= ~commonMask;
        twos &= ~commonMask;
    }
    return ones;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low <= 0 && high >= 0) {
        result.add(0);
    }

    if (high < 1) {
        Collections.sort(result);
        return result;
    }

    Queue<Long> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }

    while (!queue.isEmpty()) {
        long current = queue.poll();
        if (current > high) {
            continue;
        }
        if (current >= low) {
            result.add((int) current);
        }

        int lastDigit = (int) (current % 10);

        if (lastDigit > 0) {
            long next = current * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = current * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }

    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) return 0;
    long count = 0;
    for (long p = 1; p <= n; p *= 10) {
        long high = n / (p * 10);
        int cur = (int) ((n / p) % 10);
        long low = n % p;
        if (cur == 0) {
            count += high * p;
        } else if (cur == 1) {
            count += high * p + low + 1;
        } else {
            count += (high + 1) * p;
        }
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    if (n <= 0) {
        return false;
    }
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] antiDiag = new int[m][n];
    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = 1 + (j > 0 ? horiz[i][j - 1] : 0);
                vert[i][j] = 1 + (i > 0 ? vert[i - 1][j] : 0);
                diag[i][j] = 1 + (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0);
                antiDiag[i][j] = 1 + (i > 0 && j < n - 1 ? antiDiag[i - 1][j + 1] : 0);
                int currentMax = Math.max(
                        Math.max(horiz[i][j], vert[i][j]),
                        Math.max(diag[i][j], antiDiag[i][j]));
                if (currentMax > maxLen) {
                    maxLen = currentMax;
                }
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    // Handle zero explicitly
    if (n == 0) {
        return "0";
    }

    boolean negative = n < 0;
    int absValue = Math.abs(n);
    String numberStr = String.valueOf(absValue);
    StringBuilder sb = new StringBuilder();

    int digitCount = 0;
    // Build the formatted string in reverse order
    for (int i = numberStr.length() - 1; i >= 0; i--) {
        sb.append(numberStr.charAt(i));
        digitCount++;
        if (digitCount == 3 && i != 0) {
            sb.append('.'); // Insert dot after every three digits
            digitCount = 0;
        }
    }

    // If the input was negative, add the minus sign
    if (negative) {
        sb.append('-');
    }

    // Reverse to get the final result
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    java.util.Arrays.sort(A);
    int n = A.length;
    if (n == 0) {
        return 1;
    }
    java.util.Set<Integer> squares = new java.util.HashSet<>();
    int maxVal = A[n - 1];
    for (int i = 1; i * i <= 2 * maxVal; i++) {
        squares.add(i * i);
    }
    boolean[] used = new boolean[n];
    return dfs(-1, used, A, squares, 0);
}

private static int dfs(int lastIndex, boolean[] used, int[] A, java.util.Set<Integer> squares, int pos) {
    int n = A.length;
    if (pos == n) {
        return 1;
    }
    int total = 0;
    for (int i = 0; i < n; i++) {
        if (used[i]) {
            continue;
        }
        // Skip duplicates: if current number equals previous and previous not used yet
        if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) {
            continue;
        }
        if (lastIndex == -1 || squares.contains(A[i] + A[lastIndex])) {
            used[i] = true;
            total += dfs(i, used, A, squares, pos + 1);
            used[i] = false;
        }
    }
    return total;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = -1;
    int maxArea = 0;

    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (top >= 0 && currentHeight < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top >= 0) ? i - stack[top] - 1 : i;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length;
    if (m == 0) {
        return new int[0];
    }
    int n = mat[0].length;
    if (n == 0) {
        return new int[0];
    }
    int[] res = new int[m * n];
    int idx = 0;
    for (int s = 0; s <= m + n - 2; s++) {
        if (s % 2 == 0) {
            // even sums: traverse from bottom to top
            int iStart = Math.min(s, m - 1);
            int iEnd = Math.max(0, s - n + 1);
            for (int i = iStart; i >= iEnd; i--) {
                int j = s - i;
                res[idx++] = mat[i][j];
            }
        } else {
            // odd sums: traverse from top to bottom
            int iStart = Math.max(0, s - n + 1);
            int iEnd = Math.min(s, m - 1);
            for (int i = iStart; i <= iEnd; i++) {
                int j = s - i;
                res[idx++] = mat[i][j];
            }
        }
    }
    return res;
}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1;
    }
    int j = digits.length - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }
    // swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // reverse the suffix starting at i+1
    int left = i + 1;
    int right = digits.length - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    long result = Long.parseLong(new String(digits));
    if (result > Integer.MAX_VALUE) {
        return -1;
    }
    return (int) result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[] cur = new char[n];
    backtrack(0, n - 1, cur, n, result);
    return result;
}

private static void backtrack(int left, int right, char[] cur, int n, List<String> out) {
    if (left > right) {
        out.add(new String(cur));
        return;
    }
    if (left == right) {
        char[] mids = {'0', '1', '8'};
        for (char c : mids) {
            cur[left] = c;
            backtrack(left + 1, right - 1, cur, n, out);
        }
        return;
    }
    String[] pairs = {"00", "11", "69", "88", "96"};
    for (String p : pairs) {
        if (left == 0 && p.charAt(0) == '0' && n != 1) {
            continue;
        }
        cur[left] = p.charAt(0);
        cur[right] = p.charAt(1);
        backtrack(left + 1, right - 1, cur, n, out);
    }
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    int cross = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1);
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int max = 1;
    int current = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            current++;
        } else {
            if (current > max) {
                max = current;
            }
            current = 1;
        }
    }
    if (current > max) {
        max = current;
    }
    return max;
}

public static List<Integer> lexicalOrder(int n) {
    java.util.List<Integer> result = new java.util.ArrayList<>(n);
    int cur = 1;
    for (int i = 0; i < n; i++) {
        result.add(cur);
        if (cur * 10 <= n) {
            cur *= 10;
        } else {
            while (cur % 10 == 9 || cur + 1 > n) {
                cur /= 10;
            }
            cur++;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    Map<Integer, Integer> freq = new HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // maximum case: all ones
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            dp[i] = Math.min(dp[i], dp[i - square] + 1);
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.length() == 0) {
        return s;
    }
    StringBuilder result = new StringBuilder();
    int start = 0;
    int i = 0;
    while (i < s.length()) {
        if (s.charAt(i) == ' ') {
            for (int j = i - 1; j >= start; j--) {
                result.append(s.charAt(j));
            }
            result.append(' ');
            i++;
            start = i;
        } else {
            i++;
        }
    }
    for (int j = s.length() - 1; j >= start; j--) {
        result.append(s.charAt(j));
    }
    return result.toString();
}
